S, P, D = "shloka", "pad", "doha"

_G = "\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥"
BHAVANI_ASHTAKAM = [
 (S,"न तातो न माता न बन्धुर्न दाता\nन पुत्रो न पुत्री न भृत्यो न भर्ता।\nन जाया न विद्या न वृत्तिर्ममैव" + _G,
  "हे भवानी, न पिता, न माता, न भाई, न कोई देने वाला; न बेटा, न बेटी, न सेवक, न स्वामी; न पत्नी, न विद्या, न रोज़गार — इनमें से कोई भी सच में मेरा नहीं। मेरी गति, मेरा सहारा केवल आप हैं, केवल आप।"),
 (S,"भवाब्धावपारे महादुःखभीरु\nपपात प्रकामी प्रलोभी प्रमत्तः।\nकुसंसारपाशप्रबद्धः सदाहं" + _G,
  "मैं इस अपार संसार-सागर में गिरा पड़ा हूँ, बड़े दुखों से डरता हूँ; कामनाओं, लालच और लापरवाही से भरा हूँ और बुरे संसार के जाल में सदा बँधा रहता हूँ। हे भवानी, मेरा सहारा केवल आप हैं।"),
 (S,"न जानामि दानं न च ध्यानयोगं\nन जानामि तन्त्रं न च स्तोत्रमन्त्रम्।\nन जानामि पूजां न च न्यासयोगं" + _G,
  "मैं न दान जानता हूँ, न ध्यान-योग; न तंत्र जानता हूँ, न स्तोत्र और मंत्र; न पूजा की विधि जानता हूँ, न न्यास। हे भवानी, फिर भी मेरी गति केवल आप हैं।"),
 (S,"न जानामि पुण्यं न जानामि तीर्थं\nन जानामि मुक्तिं लयं वा कदाचित्।\nन जानामि भक्तिं व्रतं वापि मात-" + _G.replace("\n","\nर्"),
  "मैं न पुण्य जानता हूँ, न तीर्थ; न मुक्ति जानता हूँ, न ईश्वर में लीन होना; हे माँ, न भक्ति जानता हूँ, न व्रत। मेरा सहारा केवल आप हैं।"),
 (S,"कुकर्मी कुसङ्गी कुबुद्धिः कुदासः\nकुलाचारहीनः कदाचारलीनः।\nकुदृष्टिः कुवाक्यप्रबन्धः सदाहं" + _G,
  "मैं बुरे काम करने वाला, बुरी संगत वाला, बुरी बुद्धि वाला और बुरा सेवक हूँ; कुल की मर्यादा से हीन, बुरे आचरण में डूबा, बुरी नज़र और कड़वे बोल वाला हूँ। ऐसे मुझ पर भी — हे भवानी, आप ही मेरा सहारा हैं।"),
 (S,"प्रजेशं रमेशं महेशं सुरेशं\nदिनेशं निशीथेश्वरं वा कदाचित्।\nन जानामि चान्यत् सदाहं शरण्ये" + _G,
  "ब्रह्मा, विष्णु, शिव, इंद्र, सूर्य या चंद्रमा — मैं किसी और को कभी नहीं जानता। हे शरण देने वाली माँ, मेरी गति सदा केवल आप हैं।"),
 (S,"विवादे विषादे प्रमादे प्रवासे\nजले चानले पर्वते शत्रुमध्ये।\nअरण्ये शरण्ये सदा मां प्रपाहि" + _G,
  "झगड़े में, दुख में, भूल में, परदेस में; पानी में, आग में, पहाड़ पर, शत्रुओं के बीच और जंगल में — हे शरण देने वाली, सदा मेरी रक्षा कीजिए। मेरा सहारा केवल आप हैं।"),
 (S,"अनाथो दरिद्रो जरारोगयुक्तो\nमहाक्षीणदीनः सदा जाड्यवक्त्रः।\nविपत्तौ प्रविष्टः प्रणष्टः सदाहं" + _G,
  "मैं अनाथ हूँ, गरीब हूँ, बुढ़ापे और रोग से घिरा हूँ; बहुत कमज़ोर और दीन हूँ, मेरे मुँह से बात तक ठीक नहीं निकलती; विपत्ति में फँसा, पूरी तरह टूटा हुआ हूँ। हे भवानी, मेरी गति केवल आप हैं।"),
 (P,"इति श्रीमच्छङ्कराचार्यकृतं भवान्यष्टकं सम्पूर्णम्।","इस प्रकार श्री आदि शंकराचार्य द्वारा रचित भवानी अष्टक पूरा हुआ।"),
]

HANUMAN_STAVAN = [
 (D,"प्रनवउँ पवनकुमार खल बन पावक ग्यानघन।\nजासु हृदय आगार बसहिं राम सर चाप धर॥",
  "मैं पवनपुत्र हनुमान को प्रणाम करता हूँ, जो दुष्टों के वन को जलाने वाली आग जैसे और ज्ञान से भरे हैं; जिनके हृदय रूपी घर में धनुष-बाण धारी श्रीराम निवास करते हैं। (रामचरितमानस, बालकांड)"),
 (S,"अतुलितबलधामं हेमशैलाभदेहं\nदनुजवनकृशानुं ज्ञानिनामग्रगण्यम्।\nसकलगुणनिधानं वानराणामधीशं\nरघुपतिप्रियभक्तं वातजातं नमामि॥",
  "अतुलनीय बल के धाम, सोने के पर्वत जैसे शरीर वाले, राक्षसों के वन के लिए अग्नि, ज्ञानियों में सबसे आगे, सब गुणों के भंडार, वानरों के स्वामी, श्रीराम के प्रिय भक्त पवनपुत्र को मैं नमस्कार करता हूँ। (रामचरितमानस, सुंदरकांड)"),
 (S,"गोष्पदीकृतवारीशं मशकीकृतराक्षसम्।\nरामायणमहामालारत्नं वन्देऽनिलात्मजम्॥",
  "जिन्होंने समुद्र को गाय के खुर के गड्ढे जितना छोटा बना दिया और राक्षसों को मच्छर जैसा तुच्छ कर दिया, जो रामायण रूपी महामाला के रत्न हैं — उन पवनपुत्र की मैं वंदना करता हूँ।"),
 (S,"अञ्जनानन्दनं वीरं जानकीशोकनाशनम्।\nकपीशमक्षहन्तारं वन्दे लङ्काभयङ्करम्॥",
  "अंजनी के पुत्र, वीर, सीता माता का शोक मिटाने वाले, वानरों के स्वामी, रावण-पुत्र अक्षकुमार को मारने वाले और लंका को भयभीत करने वाले हनुमान की मैं वंदना करता हूँ।"),
 (S,"उल्लङ्घ्य सिन्धोः सलिलं सलीलं\nयः शोकवह्निं जनकात्मजायाः।\nआदाय तेनैव ददाह लङ्कां\nनमामि तं प्राञ्जलिराञ्जनेयम्॥",
  "जिन्होंने खेल-खेल में समुद्र का जल लाँघ लिया, और सीता माता के शोक की आग लेकर उसी से लंका जला दी — उन अंजनी-नंदन को मैं हाथ जोड़कर नमस्कार करता हूँ।"),
 (S,"मनोजवं मारुततुल्यवेगं\nजितेन्द्रियं बुद्धिमतां वरिष्ठम्।\nवातात्मजं वानरयूथमुख्यं\nश्रीरामदूतं शरणं प्रपद्ये॥",
  "मन जैसी गति और हवा जैसे वेग वाले, इंद्रियों को जीतने वाले, बुद्धिमानों में श्रेष्ठ, पवन-पुत्र, वानर-सेना के प्रमुख श्रीराम-दूत की मैं शरण लेता हूँ।"),
 (S,"आञ्जनेयमतिपाटलाननं\nकाञ्चनाद्रिकमनीयविग्रहम्।\nपारिजाततरुमूलवासिनं\nभावयामि पवमाननन्दनम्॥",
  "गहरे लाल मुख वाले, सोने के पर्वत जैसे सुंदर शरीर वाले, पारिजात वृक्ष की जड़ में निवास करने वाले अंजनी-पुत्र, पवन-नंदन का मैं ध्यान करता हूँ।"),
 (S,"यत्र यत्र रघुनाथकीर्तनं\nतत्र तत्र कृतमस्तकाञ्जलिम्।\nबाष्पवारिपरिपूर्णलोचनं\nमारुतिं नमत राक्षसान्तकम्॥",
  "जहाँ-जहाँ श्रीराम का कीर्तन होता है, वहाँ-वहाँ सिर पर हाथ जोड़े, आँखों में प्रेम के आँसू भरे हनुमान जी मौजूद रहते हैं — राक्षसों का अंत करने वाले उन मारुति को नमस्कार करो।"),
]

VINDHYESHWARI_AARTI = [
 (P,"सुन मेरी देवी पर्वतवासनी, कोई तेरा पार न पाया।\nपान सुपारी ध्वजा नारियल, ले तेरी भेंट चढ़ाया॥",
  "हे पर्वत पर रहने वाली देवी, मेरी विनती सुनो — आपकी महिमा का पार कोई नहीं पा सका। पान, सुपारी, ध्वजा और नारियल लेकर मैंने आपको भेंट चढ़ाई है।"),
 (P,"सुवा चोली तेरे अंग विराजे, केसर तिलक लगाया।\nनंगे पग माँ अकबर आया, सोने का छत्र चढ़ाया॥",
  "आपके अंग पर हरी (तोते के रंग की) चोली शोभा देती है और माथे पर केसर का तिलक है। लोककथा है कि बादशाह अकबर भी नंगे पाँव आपके दरबार आया और सोने का छत्र चढ़ाया।"),
 (P,"ऊँचे पर्वत बन्यो देवालय, नीचे शहर बसाया।\nसतयुग द्वापर त्रेता मध्ये, कलियुग राज सवाया॥",
  "ऊँचे पर्वत पर आपका मंदिर बना है और नीचे नगर बसा है। सतयुग, त्रेता और द्वापर में भी आपकी महिमा थी, और कलियुग में आपका राज सवाया (और भी बढ़कर) है।"),
 (P,"धूप दीप नैवेद्य आरती, मोहन भोग लगाया।\nध्यानू भगत मैया तेरे गुण गाया, मनवांछित फल पाया॥",
  "धूप, दीप, नैवेद्य और आरती के साथ मीठा भोग लगाया है। माँ, भक्त ध्यानू ने आपके गुण गाए और मनचाहा फल पाया।"),
 (P,"सुन मेरी देवी पर्वतवासनी, कोई तेरा पार न पाया॥","आरती का समापन फिर से पहली पंक्ति से — हे पर्वतवासिनी माँ, आपकी महिमा अपार है।"),
]

SHENDUR_LAL_AARTI = [
 (P,"शेंदुर लाल चढ़ायो अच्छा गजमुखको।\nदोंदिल लाल बिराजे सुत गौरीहरको।\nहाथ लिए गुड़लड्डू साँई सुरवरको।\nमहिमा कहे न जाय लागत हूँ पदको॥",
  "हाथी के मुख वाले गणेश जी को सुंदर लाल सिंदूर चढ़ाया गया है। बड़े पेट वाले, लाल रंग में शोभित, गौरी और शिव के पुत्र हाथ में गुड़ के लड्डू लिए हैं — देवताओं में श्रेष्ठ उन स्वामी की महिमा कही नहीं जाती, मैं उनके चरणों में प्रणाम करता हूँ।"),
 (P,"जय देव जय देव, जय जय श्री गणराज।\nविद्या सुखदाता, धन्य तुम्हारो दर्शन, मेरा मन रमता॥",
  "हे देव, हे गणराज, आपकी जय हो! आप विद्या और सुख देने वाले हैं। आपका दर्शन धन्य है — मेरा मन उसी में रम जाता है। (टेक — हर पद के बाद गाई जाती है)"),
 (P,"अष्टौ सिद्धि दासी संकटको बैरी।\nविघ्नविनाशन मंगल मूरत अधिकारी।\nकोटि सूरज प्रकाश ऐसी छबि तेरी।\nगंडस्थल मदमस्तक झूले शशिबिहारी॥",
  "आठों सिद्धियाँ आपकी दासी हैं और आप संकटों के शत्रु हैं। आप विघ्नों का नाश करने वाले, मंगल की मूर्ति और सबके अधिकारी हैं। आपकी छवि करोड़ों सूर्यों जैसी चमकती है; आपके मस्तक पर चंद्रमा शोभा देता है।"),
 (P,"भाव भगत से कोई शरणागत आवे।\nसंतति संपति सबही भरपूर पावे।\nऐसे तुम महाराज मोको अति भावे।\nगोसावीनंदन निशिदिन गुण गावे॥",
  "जो भी भाव और भक्ति से आपकी शरण में आता है, वह संतान, संपत्ति — सब कुछ भरपूर पाता है। हे महाराज, आप मुझे ऐसे ही बहुत प्रिय हैं; गोसावी-नंदन (रचनाकार) दिन-रात आपके गुण गाते हैं।"),
 (P,"जय देव जय देव, जय जय श्री गणराज।\nविद्या सुखदाता, धन्य तुम्हारो दर्शन, मेरा मन रमता॥","आरती का समापन टेक के साथ — हे गणराज, आपकी जय हो।"),
]

_T = "\nओ मैया हम सब उतारें तेरी आरती॥"
AMBE_TU_HAI_JAGDAMBE = [
 (P,"अम्बे तू है जगदम्बे काली, जय दुर्गे खप्पर वाली।\nतेरे ही गुण गाएँ भारती।" + _T,
  "हे माँ अम्बे, आप ही जगदम्बा और काली हैं; खप्पर धारण करने वाली दुर्गा माँ, आपकी जय हो। सारा भारत आपके गुण गाता है — हे मैया, हम सब आपकी आरती उतारते हैं। (टेक)"),
 (P,"तेरे भक्त जनों पर, भीड़ पड़ी है भारी माँ।\nदानव दल पर टूट पड़ो, माँ करके सिंह सवारी॥\nसौ-सौ सिंहों से बलशाली, अष्ट भुजाओं वाली,\nदुष्टों को पल में संहारती।" + _T,
  "माँ, आपके भक्तों पर भारी संकट आ पड़ा है। सिंह पर सवार होकर राक्षसों के दल पर टूट पड़ो। आप सैकड़ों सिंहों से अधिक बलवान और आठ भुजाओं वाली हैं, जो दुष्टों का पल भर में संहार कर देती हैं।"),
 (P,"माँ बेटे का है इस जग में, बड़ा ही निर्मल नाता।\nपूत-कपूत सुने हैं पर ना, माता सुनी कुमाता॥\nसब पे करुणा दरसाने वाली, अमृत बरसाने वाली,\nदुखियों के दुखड़े निवारती।" + _T,
  "इस संसार में माँ और बेटे का रिश्ता सबसे पवित्र है। बेटे के कपूत होने की बात तो सुनी है, पर माता कभी कुमाता नहीं सुनी गई। आप सब पर करुणा दिखाती हैं, अमृत बरसाती हैं और दुखियों के दुख दूर करती हैं।"),
 (P,"नहीं माँगते धन और दौलत, ना चाँदी ना सोना माँ।\nहम तो माँगें माँ तेरे मन में, इक छोटा सा कोना॥\nसबकी बिगड़ी बनाने वाली, लाज बचाने वाली,\nसतियों के सत को सँवारती।" + _T,
  "माँ, हम धन-दौलत, चाँदी या सोना नहीं माँगते — बस आपके मन में एक छोटा-सा कोना चाहते हैं। आप सबकी बिगड़ी बनाती हैं, लाज बचाती हैं और सती-साध्वी स्त्रियों के सत की रक्षा करती हैं।"),
 (P,"चरण शरण में खड़े तुम्हारी, ले पूजा की थाली।\nवरद हस्त सर पर रख दो, माँ संकट हरने वाली॥\nमाँ भर दो भक्ति रस प्याली, अष्ट भुजाओं वाली,\nभक्तों के कारज तू ही सारती।" + _T,
  "पूजा की थाली लेकर हम आपके चरणों की शरण में खड़े हैं। हे संकट हरने वाली माँ, हमारे सिर पर वरदान देने वाला हाथ रख दो। हे आठ भुजाओं वाली, हमारा भक्ति-रस का प्याला भर दो — भक्तों के सारे काम आप ही पूरे करती हैं।"),
]

C = "chaupai"
SANTOSHI_CHALISA = [
 (D,"बन्दौं सन्तोषी चरण, रिद्धि-सिद्धि दातार।\nध्यान धरत ही होत नर, दुःख सागर से पार॥","मैं रिद्धि-सिद्धि देने वाली संतोषी माता के चरणों की वंदना करता हूँ; उनका ध्यान करते ही मनुष्य दुखों के सागर से पार हो जाता है।"),
 (D,"भक्तन को सन्तोष दे, सन्तोषी तव नाम।\nकृपा करहु जगदम्ब अब, आया तेरे धाम॥","आप भक्तों को संतोष देती हैं, इसीलिए आपका नाम संतोषी है। हे जगदंबा, अब कृपा कीजिए — मैं आपके धाम आया हूँ।"),
 (C,"जय सन्तोषी मात अनूपम।\nशान्ति दायिनी रूप मनोरम॥","अनुपम संतोषी माता की जय हो; आप शांति देने वाली हैं और आपका रूप मन को मोह लेता है।"),
 (C,"सुन्दर वरण चतुर्भुज रूपा।\nवेश मनोहर ललित अनूपा॥","आपका रंग सुंदर है, आप चार भुजाओं वाली हैं, और आपका वेश मनोहर, कोमल और अनोखा है।"),
 (C,"श्वेताम्बर रूप मनहारी।\nमाँ तुम्हारी छवि जग से न्यारी॥","सफ़ेद वस्त्रों में आपका रूप मन हर लेता है; माँ, आपकी छवि पूरे संसार से निराली है।"),
 (C,"दिव्य स्वरूपा आयत लोचन।\nदर्शन से हो संकट मोचन॥","आपका स्वरूप दिव्य है और नेत्र बड़े-बड़े हैं; आपके दर्शन से संकट छूट जाते हैं।"),
 (C,"जय गणेश की सुता भवानी।\nरिद्धि-सिद्धि की पुत्री ज्ञानी॥","हे भवानी, आपकी जय हो — आप गणेश जी की बेटी और रिद्धि-सिद्धि की ज्ञानवान पुत्री हैं।"),
 (C,"अगम अगोचर तुम्हरी माया।\nसब पर करो कृपा की छाया॥","आपकी माया न समझ में आती है, न आँखों से दिखती है; सब पर अपनी कृपा की छाया कीजिए।"),
 (C,"नाम अनेक तुम्हारे माता।\nअखिल विश्व है तुमको ध्याता॥","माँ, आपके अनेक नाम हैं और सारा संसार आपका ध्यान करता है।"),
 (C,"तुमने रूप अनेकों धारे।\nको कहि सके चरित्र तुम्हारे॥","आपने अनेक रूप धारण किए हैं; आपकी लीलाओं का वर्णन कौन कर सकता है?"),
 (C,"धाम अनेक कहाँ तक कहिये।\nसुमिरन तब करके सुख लहिये॥","आपके कितने धाम गिनाएँ? आपका स्मरण करके ही सुख मिलता है।"),
 (C,"विन्ध्याचल में विन्ध्यवासिनी।\nकोटेश्वर सरस्वती सुहासिनी॥","विंध्याचल में आप विंध्यवासिनी हैं, और कोटेश्वर में मधुर मुस्कान वाली सरस्वती।"),
 (C,"कलकत्ते में तू ही काली।\nदुष्ट नाशिनी महाकराली॥","कलकत्ते में आप ही काली हैं — दुष्टों का नाश करने वाली महाकराली।"),
 (C,"सम्बलपुर बहुचरा कहाती।\nभक्तजनों का दुःख मिटाती॥","संबलपुर में आप बहुचरा माता कहलाती हैं और भक्तों का दुख मिटाती हैं।"),
 (C,"ज्वाला जी में ज्वाला देवी।\nपूजत नित्य भक्त जन सेवी॥","ज्वाला जी में आप ज्वाला देवी हैं, जहाँ सेवा करने वाले भक्त रोज़ आपकी पूजा करते हैं।"),
 (C,"नगर बम्बई की महारानी।\nमहालक्ष्मी तुम कल्याणी॥","मुंबई नगर की महारानी, कल्याण करने वाली महालक्ष्मी आप ही हैं।"),
 (C,"मदुरा में मीनाक्षी तुम हो।\nसुख दुख सबकी साक्षी तुम हो॥","मदुरै में आप मीनाक्षी हैं; सबके सुख-दुख की साक्षी आप ही हैं।"),
 (C,"राजनगर में तुम जगदम्बे।\nबनी भद्रकाली तुम अम्बे॥","राजनगर में आप जगदंबा हैं; हे अम्बे, वहाँ आप भद्रकाली बनकर विराजती हैं।"),
 (C,"पावागढ़ में दुर्गा माता।\nअखिल विश्व तेरा यश गाता॥","पावागढ़ में आप दुर्गा माता हैं; पूरा संसार आपका यश गाता है।"),
 (C,"काशी पुराधीश्वरी माता।\nअन्नपूर्णा नाम सुहाता॥","काशी नगरी की स्वामिनी माता, वहाँ आपका अन्नपूर्णा नाम शोभा देता है।"),
 (C,"सर्वानन्द करो कल्याणी।\nतुम्हीं शारदा अमृत वाणी॥","हे कल्याणी, सबको आनंद दीजिए; अमृत जैसी वाणी वाली शारदा (सरस्वती) भी आप ही हैं।"),
 (C,"तुम्हरी महिमा जल में थल में।\nदुःख दारिद्र सब मेटो पल में॥","आपकी महिमा जल और थल में हर जगह है; आप दुख और दरिद्रता पल भर में मिटा देती हैं।"),
 (C,"जेते ऋषि और मुनीशा।\nनारद देव और देवेशा॥","जितने भी ऋषि, मुनि, नारद जी, देवता और देवराज इंद्र हैं —"),
 (C,"इस जगती के नर और नारी।\nध्यान धरत हैं मात तुम्हारी॥","— और इस संसार के सभी स्त्री-पुरुष, हे माँ, आपका ही ध्यान करते हैं।"),
 (C,"जापर कृपा तुम्हारी होती।\nवह पाता भक्ति का मोती॥","जिस पर आपकी कृपा होती है, वही भक्ति रूपी मोती पाता है।"),
 (C,"दुःख दारिद्र संकट मिट जाता।\nध्यान तुम्हारा जो जन ध्याता॥","जो आपका ध्यान करता है, उसके दुख, दरिद्रता और संकट मिट जाते हैं।"),
 (C,"जो जन तुम्हरी महिमा गावै।\nध्यान तुम्हारा कर सुख पावै॥","जो आपकी महिमा गाता है, वह आपका ध्यान करके सुख पाता है।"),
 (C,"जो मन राखे शुद्ध भावना।\nताकी पूरण करो कामना॥","जो मन में शुद्ध भाव रखता है, आप उसकी कामना पूरी करती हैं।"),
 (C,"कुमति निवारि सुमति की दात्री।\nजयति जयति माता जगधात्री॥","आप बुरी बुद्धि हटाकर अच्छी बुद्धि देती हैं; संसार को धारण करने वाली माता, आपकी जय हो।"),
 (C,"शुक्रवार का दिवस सुहावन।\nजो व्रत करे तुम्हारा पावन॥","शुक्रवार का दिन बहुत शुभ है; जो इस दिन आपका पवित्र व्रत करता है —"),
 (C,"गुड़ छोले का भोग लगावै।\nकथा तुम्हारी सुने सुनावै॥","— गुड़ और चने का भोग लगाता है, आपकी कथा सुनता और सुनाता है —"),
 (C,"विधिवत पूजा करे तुम्हारी।\nफिर प्रसाद पावे शुभकारी॥","— विधि से आपकी पूजा करता है और फिर शुभ प्रसाद ग्रहण करता है —"),
 (C,"शक्ति-सामर्थ्य हो जो धन को।\nदान-दक्षिणा दे विप्रन को॥","— और अपनी सामर्थ्य के अनुसार ब्राह्मणों को दान-दक्षिणा देता है,"),
 (C,"वे जगती के नर औ नारी।\nमनवांछित फल पावें भारी॥","संसार के ऐसे सभी स्त्री-पुरुष भरपूर मनचाहा फल पाते हैं।"),
 (C,"जो जन शरण तुम्हारी जावे।\nसो निश्चय भव से तर जावे॥","जो आपकी शरण में जाता है, वह निश्चय ही संसार-सागर से पार हो जाता है।"),
 (C,"तुम्हरो ध्यान कुमारी ध्यावे।\nनिश्चय मनवांछित वर पावै॥","जो कुंवारी कन्या आपका ध्यान करती है, उसे निश्चय ही मनचाहा वर मिलता है।"),
 (C,"सधवा पूजा करे तुम्हारी।\nअमर सुहागिन हो वह नारी॥","जो सुहागिन आपकी पूजा करती है, उसका सुहाग अमर रहता है।"),
 (C,"विधवा धर के ध्यान तुम्हारा।\nभवसागर से उतरे पारा॥","विधवा स्त्री भी आपका ध्यान करके संसार-सागर से पार उतर जाती है।"),
 (C,"जयति जयति जय संकट हरणी।\nविघ्न विनाशन मंगल करनी॥","संकट हरने वाली, विघ्नों का नाश करने वाली और मंगल करने वाली माँ, आपकी जय हो, जय हो।"),
 (C,"हम पर संकट है अति भारी।\nवेगि खबर लो मात हमारी॥","माँ, हम पर बहुत भारी संकट है; जल्दी हमारी सुध लीजिए।"),
 (C,"निशिदिन ध्यान तुम्हारो ध्याता।\nदेह भक्ति वर हम को माता॥","हम दिन-रात आपका ध्यान करते हैं; हे माता, हमें भक्ति का वरदान दीजिए।"),
 (C,"यह चालीसा जो नित गावे।\nसो भवसागर से तर जावे॥","जो यह चालीसा रोज़ गाता है, वह संसार-सागर से पार हो जाता है।"),
 (D,"संतोषी माँ के सदा, बंदहूँ पग निशि वास।\nपूर्ण मनोरथ हो सकल, मात हरौ भव त्रास॥","मैं दिन-रात संतोषी माँ के चरणों की वंदना करता हूँ; माँ, मेरे सब मनोरथ पूरे कीजिए और संसार का भय हर लीजिए।"),
]

PITAR_CHALISA = [
 (D,"हे पितरेश्वर आपको, दे दियो आशीर्वाद।\nचरणाशीश नवा दियो, रखदो सिर पर हाथ॥","हे पितरेश्वर, हमें आशीर्वाद दीजिए। हमने आपके चरणों में सिर झुकाया है — हमारे सिर पर हाथ रख दीजिए।"),
 (D,"सबसे पहले गणपत, पाछे घर का देव मनावा जी।\nहे पितरेश्वर दया राखियो, करियो मन की चाया जी॥","सबसे पहले गणपति को, फिर घर के देवता को मनाते हैं। हे पितरेश्वर, दया बनाए रखना और मन की इच्छा पूरी करना।"),
 (C,"पितरेश्वर करो मार्ग उजागर।\nचरण रज की मुक्ति सागर॥","हे पितरेश्वर, हमारा रास्ता रोशन कीजिए; आपके चरणों की धूल मुक्ति का सागर है।"),
 (C,"परम उपकार पितरेश्वर कीन्हा।\nमनुष्य योनि में जन्म दीन्हा॥","पितरों ने हम पर सबसे बड़ा उपकार किया — हमें मनुष्य के रूप में जन्म दिया।"),
 (C,"मातृ-पितृ देव मन जो भावे।\nसोई अमित जीवन फल पावे॥","जिसके मन को माता-पिता रूपी देव भाते हैं, वही जीवन का असीम फल पाता है।"),
 (C,"जै जै जै पित्तर जी साईं।\nपितृ ऋण बिन मुक्ति नाहिं॥","हे स्वामी पितर जी, आपकी जय हो! पितृ-ऋण चुकाए बिना मुक्ति नहीं मिलती।"),
 (C,"चारों ओर प्रताप तुम्हारा।\nसंकट में तेरा ही सहारा॥","चारों ओर आपका प्रताप फैला है; संकट में आपका ही सहारा है।"),
 (C,"नारायण आधार सृष्टि का।\nपित्तर जी अंश उसी दृष्टि का॥","भगवान नारायण सृष्टि के आधार हैं, और पितर उन्हीं की दृष्टि के अंश हैं।"),
 (C,"प्रथम पूजन प्रभु आज्ञा सुनाते।\nभाग्य द्वार आप ही खुलवाते॥","प्रभु की आज्ञा है कि पहले पितरों का पूजन हो; भाग्य के दरवाज़े आप ही खुलवाते हैं।"),
 (C,"झुंझुनू में दरबार है साजे।\nसब देवों संग आप विराजे॥","झुंझुनू (राजस्थान) में आपका दरबार सजा है, जहाँ आप सब देवताओं के साथ विराजते हैं।"),
 (C,"प्रसन्न होय मनवांछित फल दीन्हा।\nकुपित होय बुद्धि हर लीन्हा॥","प्रसन्न होने पर आप मनचाहा फल देते हैं, और नाराज़ होने पर बुद्धि हर लेते हैं।"),
 (C,"पित्तर महिमा सबसे न्यारी।\nजिसका गुण गावे नर नारी॥","पितरों की महिमा सबसे निराली है, जिसका गुण सभी स्त्री-पुरुष गाते हैं।"),
 (C,"तीन मण्ड में आप बिराजे।\nबसु रुद्र आदित्य में साजे॥","आप तीनों मंडलों में विराजते हैं — वसु, रुद्र और आदित्य रूप में (श्राद्ध में पिता, दादा और परदादा इन्हीं रूपों में पूजे जाते हैं)।"),
 (C,"नाथ सकल संपदा तुम्हारी।\nमैं सेवक समेत सुत नारी॥","हे नाथ, सारी संपत्ति आपकी ही दी हुई है; मैं अपने बेटे और पत्नी सहित आपका सेवक हूँ।"),
 (C,"छप्पन भोग नहीं हैं भाते।\nशुद्ध जल से ही तृप्त हो जाते॥","आपको छप्पन भोग नहीं चाहिए; आप तो शुद्ध जल से ही तृप्त हो जाते हैं।"),
 (C,"तुम्हारे भजन परम हितकारी।\nछोटे बड़े सभी अधिकारी॥","आपका भजन सबसे हितकारी है, और छोटे-बड़े सभी इसके अधिकारी हैं।"),
 (C,"भानु उदय संग आप पुजावै।\nपांच अँजुलि जल रिझावे॥","सूर्योदय के साथ आपकी पूजा होती है; पाँच अंजलि जल (तर्पण) से आप प्रसन्न हो जाते हैं।"),
 (C,"ध्वज पताका मण्ड पे है साजे।\nअखण्ड ज्योति में आप विराजे॥","आपके मंडप पर ध्वजा-पताका सजी है और आप अखंड ज्योति में विराजते हैं।"),
 (C,"सदियों पुरानी ज्योति तुम्हारी।\nधन्य हुई जन्म भूमि हमारी॥","आपकी ज्योति सदियों पुरानी है, जिससे हमारी जन्मभूमि धन्य हो गई।"),
 (C,"शहीद हमारे यहाँ पुजाते।\nमातृ भक्ति संदेश सुनाते॥","हमारे यहाँ शहीद भी पूजे जाते हैं, जो मातृभूमि की भक्ति का संदेश देते हैं।"),
 (C,"जगत पित्तरो सिद्धान्त हमारा।\nधर्म जाति का नहीं है नारा॥","पूरे जगत के पितरों का सम्मान हमारा सिद्धांत है; इसमें धर्म या जाति का भेद नहीं।"),
 (C,"हिन्दू, मुस्लिम, सिख, ईसाई।\nसब पूजे पित्तर भाई॥","हिंदू, मुस्लिम, सिख, ईसाई — सभी अपने पूर्वजों को पूजते हैं।"),
 (C,"हिन्दू वंश वृक्ष है हमारा।\nजान से ज्यादा हमको प्यारा॥","हमारा वंश-वृक्ष हमें जान से भी ज़्यादा प्यारा है।"),
 (C,"गंगा ये मरुप्रदेश की।\nपितृ तर्पण अनिवार्य परिवेश की॥","यह (पितरों की धारा) मरुभूमि की गंगा है; यहाँ के परिवेश में पितृ-तर्पण आवश्यक माना जाता है।"),
 (C,"बन्धु छोड़ ना इनके चरणाँ।\nइन्हीं की कृपा से मिले प्रभु शरणा॥","हे भाई, इनके चरण कभी मत छोड़ना; इन्हीं की कृपा से प्रभु की शरण मिलती है।"),
 (C,"चौदस को जागरण करवाते।\nअमावस को हम धोक लगाते॥","चतुर्दशी को जागरण करवाते हैं और अमावस्या को माथा टेककर प्रणाम (धोक) करते हैं।"),
 (C,"जात जडूला सभी मनाते।\nनान्दीमुख श्राद्ध सभी करवाते॥","सब जात-जडूला (बच्चे का पहला मुंडन) मनाते हैं और शुभ कामों से पहले नांदीमुख श्राद्ध करवाते हैं।"),
 (C,"धन्य जन्म भूमि का वो फूल है।\nजिसे पितृ मण्डल की मिली धूल है॥","जन्मभूमि का वह फूल धन्य है, जिसे पितृ-मंडल की धूल मिली है।"),
 (C,"श्री पित्तर जी भक्त हितकारी।\nसुन लीजे प्रभु अरज हमारी॥","हे भक्तों का भला करने वाले पितर जी, हमारी प्रार्थना सुन लीजिए।"),
 (C,"निशदिन ध्यान धरे जो कोई।\nता सम भक्त और नहीं कोई॥","जो दिन-रात आपका ध्यान करता है, उसके समान कोई दूसरा भक्त नहीं।"),
 (C,"तुम अनाथ के नाथ सहाई।\nदीनन के हो तुम सदा सहाई॥","आप अनाथों के नाथ और सहायक हैं; आप सदा दीनों की मदद करते हैं।"),
 (C,"चारिक वेद प्रभु के साखी।\nतुम भक्तन की लज्जा राखी॥","चारों वेद इसके साक्षी हैं कि आपने सदा भक्तों की लाज रखी है।"),
 (C,"नाम तुम्हारो लेत जो कोई।\nता सम धन्य और नहीं कोई॥","जो आपका नाम लेता है, उसके समान धन्य कोई नहीं।"),
 (C,"जो तुम्हारे नित पाँव पलोटत।\nनवों सिद्धि चरणा में लोटत॥","जो रोज़ आपके पाँव दबाता (सेवा करता) है, नौ सिद्धियाँ उसके चरणों में लोटती हैं।"),
 (C,"सिद्धि तुम्हारी सब मंगलकारी।\nजो तुम पे जावे बलिहारी॥","आपकी दी हुई सिद्धियाँ सब मंगल करती हैं, उसके लिए जो आप पर न्योछावर हो जाए।"),
 (C,"जो तुम्हारे चरणा चित्त लावे।\nताकी मुक्ति अवसी हो जावे॥","जो आपके चरणों में मन लगाता है, उसकी मुक्ति अवश्य हो जाती है।"),
 (C,"सत्य भजन तुम्हारो जो गावे।\nसो निश्चय चारों फल पावे॥","जो सच्चे मन से आपका भजन गाता है, वह निश्चय ही धर्म, अर्थ, काम, मोक्ष — चारों फल पाता है।"),
 (C,"तुमहिं देव कुलदेव हमारे।\nतुम्हीं गुरुदेव प्राण से प्यारे॥","आप ही हमारे देव और कुलदेव हैं; आप ही प्राणों से प्यारे गुरुदेव हैं।"),
 (C,"सत्य आस मन में जो होई।\nमनवांछित फल पावें सोई॥","जिसके मन में सच्ची आस होती है, वही मनचाहा फल पाता है।"),
 (C,"तुम्हरी महिमा बुद्धि बड़ाई।\nशेष सहस्र मुख सके न गाई॥","आपकी महिमा और बड़ाई इतनी है कि हज़ार मुख वाले शेषनाग भी उसे गा नहीं सकते।"),
 (C,"मैं अतिदीन मलीन दुखारी।\nकरहु कौन विधि विनय तुम्हारी॥","मैं बहुत दीन, मैला और दुखी हूँ; किस विधि से आपकी विनती करूँ?"),
 (C,"अब पित्तर जी दया दीन पर कीजै।\nअपनी भक्ति शक्ति कछु दीजै॥","हे पितर जी, अब इस दीन पर दया कीजिए और अपनी भक्ति और शक्ति का कुछ अंश दीजिए।"),
 (D,"पित्तरौं को स्थान दो, तीरथ और स्वयं ग्राम।\nश्रद्धा सुमन चढ़ें वहां, पूरण हो सब काम॥","पितरों को तीर्थ में और अपने गाँव में स्थान दो; वहाँ श्रद्धा के फूल चढ़ें तो सब काम पूरे होते हैं।"),
 (D,"झुंझुनू धाम विराजे हैं, पित्तर हमारे महान।\nदर्शन से जीवन सफल हो, पूजे सकल जहान॥","हमारे महान पितर झुंझुनू धाम में विराजते हैं; उनके दर्शन से जीवन सफल होता है और सारा संसार उन्हें पूजता है।"),
 (D,"जीवन सफल जो चाहिए, चले झुंझुनू धाम।\nपित्तर चरण की धूल ले, हो जीवन सफल महान॥","जो जीवन सफल बनाना चाहे, वह झुंझुनू धाम जाए; पितरों के चरणों की धूल लेकर जीवन महान और सफल होता है।"),
]
